/bin/bash -lc "node <<'JS'
const {chromium}=require('/tmp/claude-0/-root-design/f13cfb4d-b71e-4ed8-960a-ee0a8c2a8818/scratchpad/pwnode/node_modules/playwright-core');
const assert=require('node:assert/strict');
(async()=>{
 const browser=await chromium.launch({headless:true,executablePath:'/root/.cache/ms-playwright/chromium-1140/chrome-linux/chrome',args:['--no-sandbox','--no-zygote','--single-process','--disable-gpu']});
 const page=await browser.newPage({viewport:{width:240,height:200},deviceScaleFactor:2});
 await page.goto('file://'+process.cwd()+'/caught-up.svg');
 const frames=await page.evaluate(()=>{
   const e=document.querySelector('.caught-up-envelope');
   const a=e.getAnimations()[0]; a.pause();
   const result=[];
   for(const time of [0,3000,6000]){a.currentTime=time;result.push(getComputedStyle(e).transform);}
   a.currentTime=0;return result;
 });
 assert.equal(frames[0],frames[2]);
 assert.equal(frames[1],'matrix(1, 0, 0, 1, 0, -3)');
 await page.locator('svg').screenshot({path:'/tmp/caught-up-preview.png'});
 await page.emulateMedia({reducedMotion:'reduce'});
 assert.equal(await page.locator('.caught-up-envelope').evaluate(e=>getComputedStyle(e).animationName),'none');
 assert.equal(await page.locator('.caught-up-shadow').evaluate(e=>getComputedStyle(e).animationName),'none');
 console.log('Verified: seamless 6-second loop, 3px movement, reduced-motion disables both animations.');
 await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});
JS"

